function rulerContacts(){const s=state.instruments.ruler;if(!s.visible||state.settings.rulerSnap===false)return[];const a=originPixel('ruler'),b=endPixel('ruler'),start=map.containerPointToLatLng(a),seen=new Set();return visibleSnapPoints().map(p=>{const q=map.latLngToContainerPoint(p.position),contact=rulerContact(a,b,[q.x,q.y],3);return{...p,contact,distanceM:distance([start.lat,start.lng],p.position)}}).filter(p=>{const key=p.name+','+p.position[0]+','+p.position[1];if(!p.contact||p.contact.distance<3||seen.has(key))return false;seen.add(key);return true}).sort((a,b)=>a.contact.fraction-b.contact.fraction)}
function preciseRulerDistance(m){return(m/factor(state.settings.unit)).toFixed(precision(state.settings.unit,state.settings.unit==='m'?1:4))+' '+state.settings.unit.toUpperCase()+(state.settings.unit==='m'?'':'（'+m.toFixed(precision('m',1))+' m）')}
function renderRulerContactDetails(){const contacts=rulerContacts(),floating=$('ruler-contact-info'),list=$('ruler-contact-list');if(!floating||!list)return;floating.hidden=!contacts.length;floating.replaceChildren();list.replaceChildren();if(!contacts.length){list.textContent='移動直尺靠近航點／標記，吸附後顯示距離 0 點的詳細數值。';return}const title=document.createElement('b');title.textContent='直尺 0 點 → 吸附點';floating.append(title);for(const [i,p] of contacts.entries()){const row=document.createElement('div'),name=document.createElement('b'),value=document.createElement('span'),coords=document.createElement('small');name.textContent=p.name;value.textContent=preciseRulerDistance(p.distanceM);coords.textContent=pair(p.position);row.append(name,value,coords);list.append(row);if(i<3){const line=document.createElement('p');line.textContent=p.name+' · '+preciseRulerDistance(p.distanceM);floating.append(line)}}if(contacts.length>3){const more=document.createElement('small');more.textContent='另 '+(contacts.length-3)+' 點，詳見尺規設定';floating.append(more)}const g=instrumentGeometry('ruler'),size=map.getSize();floating.style.left=Math.max(8,Math.min(Math.max(8,size.x-250),g.cx+16))+'px';floating.style.top=Math.max(8,Math.min(size.y-140,g.cy+52))+'px'}
function snapRulerBody(){if(state.settings.rulerSnap===false)return;const s=state.instruments.ruler,a=originPixel('ruler'),b=endPixel('ruler'),g=instrumentGeometry('ruler'),candidate=visibleSnapPoints().map(p=>{const at=map.latLngToContainerPoint(p.position),q=[at.x,at.y];return{...p,q,contact:rulerContact(a,b,q)}}).filter(p=>p.contact&&p.contact.distance>12).sort((a,b)=>a.contact.error-b.contact.error)[0];if(!candidate){s.contact=null;return}const snapped=snapRulerToPoint(g,a,b,candidate.q,!!s.lock);if(!snapped)return;applyInstrumentGeometry('ruler',snapped);s.contact={name:candidate.name,position:[...candidate.position]};renderInstruments()}

function settleInstrument(name){const s=state.instruments[name];if(!s.lock)snapOrigin(name);if(name==='ruler')snapRulerBody();else if(!s.lock){if(snapProtractor()){const at=map.containerPointToLatLng(originPixel(name));lockOrigin(name,[at.lat,at.lng])}}save()}
