function repairNamedRegions(){for(const layer of state.layers)for(const o of layer.objects){if(o.type!=='polygon'||o.boxInputMode==='ordered'||!Array.isArray(o.boxVertices)||o.boxVertices.length<3)continue;try{const points=orderedPolygon(o.boxVertices);o.points=points;o.boxVertices=o.boxVertices.slice(0,points.length).map((v,i)=>({name:v.name||'點 '+(i+1),position:[...points[i]]}));o.boxInputMode='ordered';repairedRegionCount++}catch{}}}
function sanitizePreferences(){if(location.search.includes('mps-offline-test=1')){state.settings.basemap='vector';state.settings.liveVehicles={};}cleanExistingVertexNames();repairNamedRegions();const defaults={unit:'nm',format:'dms',color:'#f3ba68',basemap:'vector',routes:true,fixes:true,grid:true,selectedRoutes:null,referenceVisibility:{},selectedWaypointIds:null};state.settings={...defaults,...state.settings};const s=state.settings;s.cursorDisplay=cursorVisibility(s.cursorDisplay).mode;if(!['nm','km','m'].includes(s.unit))s.unit='nm';if(!['dms','decimal'].includes(s.format))s.format='dms';if((offlineBundle&&!['vector','protomaps','sentinel2'].includes(s.basemap))||!['vector','street','satellite','protomaps','sentinel2'].includes(s.basemap))s.basemap='vector';if(!/^#[\da-f]{6}$/i.test(s.color))s.color='#f3ba68';if(s.selectedRoutes!==null)s.selectedRoutes=Array.isArray(s.selectedRoutes)?s.selectedRoutes.filter(x=>typeof x==='string').slice(0,300):null;if(!s.referenceVisibility||typeof s.referenceVisibility!=='object')s.referenceVisibility={};for(const key of ['routes','fixes','grid'])s[key]=s[key]!==false;for(const l of state.layers)l.opacity=clampOpacity(l.opacity);s.baseOpacity=clampOpacity(s.baseOpacity);s.routeOpacity=clampOpacity(s.routeOpacity);s.fixOpacity=clampOpacity(s.fixOpacity);s.referenceOpacity=s.referenceOpacity&&typeof s.referenceOpacity==='object'?s.referenceOpacity:{};for(const id of Object.keys(s.referenceOpacity))s.referenceOpacity[id]=clampOpacity(s.referenceOpacity[id]);s.customColors=Array.isArray(s.customColors)?s.customColors.filter(c=>/^#[\da-f]{6}$/i.test(c)).slice(0,2000):[];if(s.selectedWaypointIds!==null)s.selectedWaypointIds=Array.isArray(s.selectedWaypointIds)?s.selectedWaypointIds.filter(x=>typeof x==='string'):null;state.instruments||={};for(const name of ['ruler','protractor']){const data=state.instruments[name]||{};const normalized={visible:data.visible===true,x:Number.isFinite(data.x)?Math.max(0,Math.min(1,data.x)):.52,y:Number.isFinite(data.y)?Math.max(0,Math.min(.88,data.y)):.45,rotation:Number.isFinite(data.rotation)?data.rotation%360:0};if(name==='ruler'){normalized.range=null;if(data.range&&Number.isFinite(data.range.fromM)&&Number.isFinite(data.range.toM)&&data.range.fromM>=0&&data.range.toM>data.range.fromM&&/^#[\da-f]{6}$/i.test(data.range.color))normalized.range={fromM:data.range.fromM,toM:data.range.toM,color:data.range.color}}else{normalized.range=null;if(data.range&&Number.isFinite(data.range.from)&&Number.isFinite(data.range.to)&&data.range.from>=0&&data.range.from<=360&&data.range.to>=0&&data.range.to<=360&&data.range.from!==data.range.to&&/^#[\da-f]{6}$/i.test(data.range.color))normalized.range={from:data.range.from,to:data.range.to,color:data.range.color}}if(data.lock&&Array.isArray(data.lock.point)&&data.lock.point.length===2&&data.lock.point.every(Number.isFinite)&&Math.abs(data.lock.point[0])<=90&&Math.abs(data.lock.point[1])<=180)normalized.lock={point:[...data.lock.point]};if(name==='ruler'&&data.endLock&&Array.isArray(data.endLock.point)&&data.endLock.point.length===2&&data.endLock.point.every(Number.isFinite)&&Math.abs(data.endLock.point[0])<=90&&Math.abs(data.endLock.point[1])<=180)normalized.endLock={point:[...data.endLock.point]};normalized.scale=Number.isFinite(data.scale)?Math.max(.2,Math.min(3,data.scale)):1;normalized.ranges=Array.isArray(data.ranges)?data.ranges.filter(r=>r&&/^#[\da-f]{6}$/i.test(r.color)&&Number.isFinite(name==='ruler'?r.fromM:r.from)&&Number.isFinite(name==='ruler'?r.toM:r.to)).slice(0,200):data.range?[{...data.range,id:uid(),name:'標色範圍 1',visible:true}]:[];state.instruments[name]=normalized}}
$('project-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error('專案檔超過 20 MB');const imported=validateProject(JSON.parse(await file.text()));download(JSON.stringify(state,null,2),'map-workspace-before-open-'+Date.now()+'.json','application/json');snapshot();state=imported;sanitizePreferences();selected=null;$('editor-panel').hidden=true;setTool('pan');refreshUI();save('已開啟專案，原專案已下載備份')}catch(e){toast('開啟失敗：'+e.message)}e.target.value=''};
function escapeXML(s){return String(s).replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]))}
function exportKML(){const layer=activeLayer();const placemarks=layer.objects.map(o=>{const p=o.points.map(p=>`${p[1]},${p[0]},${p[2]||0}`);if(o.type==='polygon')p.push(p[0]);const coordinates='<altitudeMode>'+escapeXML(o.altitudeMode||'absolute')+'</altitudeMode><coordinates>'+p.join(' ')+'</coordinates>',geometry=o.type==='point'?'<Point>'+coordinates+'</Point>':o.type==='line'?'<LineString>'+coordinates+'</LineString>':'<Polygon><outerBoundaryIs><LinearRing>'+coordinates+'</LinearRing></outerBoundaryIs></Polygon>';const c=o.color.slice(1),color='ff'+c.slice(4,6)+c.slice(2,4)+c.slice(0,2);return`<Placemark><name>${escapeXML(o.name)}</name><description>${escapeXML(o.description||'')}</description><Style><LineStyle><color>${color}</color><width>2</width></LineStyle><PolyStyle><color>30${color.slice(2)}</color></PolyStyle><IconStyle><color>${color}</color></IconStyle></Style>${geometry}</Placemark>`}).join('');download('<?xml version="1.0" encoding="UTF-8"?><kml xmlns="http://www.opengis.net/kml/2.2"><Document><name>'+escapeXML(layer.name)+'</name>'+placemarks+'</Document></kml>',layer.name.replace(/[<>:"/\\|?*]/g,'_')+'.kml','application/vnd.google-earth.kml+xml');toast('已匯出目前圖層的 '+layer.objects.length+' 個物件')}
