$('kml-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>50*1024*1024)throw Error('KML 超過 50 MB');reportActiveProgress(5,'讀取 KML');const xml=new DOMParser().parseFromString(await file.text(),'application/xml');reportActiveProgress(15,'解析 KML');if(xml.querySelector('parsererror'))throw Error('XML 格式不正確');const tags=(root,name)=>[...root.getElementsByTagNameNS('*',name)],objects=[];const placemarks=tags(xml,'Placemark');let parsedMarks=0;for(const mark of placemarks){if(parsedMarks%40===0){reportActiveProgress(15+parsedMarks/placemarks.length*65,'解析 KML');await new Promise(r=>setTimeout(r,0))}parsedMarks++;const name=tags(mark,'name')[0]?.textContent||'匯入標繪',description=tags(mark,'description')[0]?.textContent||'';const geometries=[...mark.getElementsByTagName('*')].filter(n=>['Point','LineString','Polygon'].includes(n.localName));for(const g of geometries){if(g.localName==='Polygon'&&tags(g,'innerBoundaryIs').length)throw Error('不支援含孔洞的多邊形；請先轉為單環');const raw=tags(g,'coordinates')[0]?.textContent?.trim();if(!raw)continue;let points=raw.split(/\s+/).map(s=>{const p=s.split(',').map(Number);return[p[1],p[0],p[2]??0]});const type=g.localName==='Point'?'point':g.localName==='LineString'?'line':'polygon';if(type==='polygon'&&points.length>1&&points[0][0]===points.at(-1)[0]&&points[0][1]===points.at(-1)[1])points.pop();const rawColor=tags(mark,'color')[0]?.textContent?.trim();let color=state.settings.color;if(/^[\da-f]{8}$/i.test(rawColor))color='#'+rawColor.slice(6,8)+rawColor.slice(4,6)+rawColor.slice(2,4);objects.push({id:uid(),name,description,type,points,color,altitudeMode:tags(g,'altitudeMode')[0]?.textContent||'clampToGround'})}}if(!objects.length)throw Error('沒有 Point、LineString 或 Polygon');const layer={id:uid(),name:file.name.replace(/\.kml$/i,''),visible:true,objects};validateProject({version:2,layers:[layer],activeLayerId:layer.id});snapshot();state.layers.push(layer);state.activeLayerId=layer.id;save('已匯入 '+objects.length+' 個幾何物件，並建立獨立圖層。其他 KML 中繼資料未保留。');renderObjects();renderLayers();openPanel('layers-panel');map.fitBounds(L.latLngBounds(objects.flatMap(o=>o.points)),{padding:[40,40],maxZoom:10})}catch(e){toast('匯入失敗：'+e.message)}e.target.value=''};
