function simplifyPlaceName(name){
  return [...name].map(char=>simplifiedPlaceChars[char]||char).join('');
}
let placeRequest, placeTimer;
let placeMode=false;
const searchInput=$('global-search-input');
placeButton.setAttribute('aria-pressed','false');
function schedulePlaceSuggestions(){
  clearTimeout(placeTimer);
  placeRequest?.abort();
  if(!placeMode)return;
  $('global-search-results').replaceChildren();
  if(Array.from(searchInput.value.trim()).length<2){
    $('global-search-count').textContent='輸入至少兩個字以顯示地名建議';
    return;
  }
  placeTimer=setTimeout(requestPlaceSuggestions,650);
}
$('global-search-input').addEventListener('input',()=>placeRequest?.abort());
searchDialog.addEventListener('close',()=>{clearTimeout(placeTimer);placeRequest?.abort();});
searchInput.addEventListener('input',event=>{if(!event.isComposing)schedulePlaceSuggestions();else if(placeMode)$('global-search-results').replaceChildren();});
searchInput.addEventListener('compositionend',schedulePlaceSuggestions);
placeButton.onclick=()=>{
  placeMode=!placeMode;
  placeButton.setAttribute('aria-pressed',String(placeMode));
  placeButton.textContent=placeMode?'地名模式已開啟':'搜尋地名';
  searchInput.focus();
  schedulePlaceSuggestions();
  if(!placeMode)runGlobalSearch();
};
async function requestPlaceSuggestions(){
  const query=$('global-search-input').value.trim();
  if(!query){$('global-search-count').textContent='請先輸入地名';return;}
  if(offlineBundle||!navigator.onLine){$('global-search-count').textContent='地名搜尋需連線';return;}
  placeRequest?.abort();
  const controller=new AbortController();
  placeRequest=controller;
  const timeout=setTimeout(()=>controller.abort('timeout'),10000);
  const count=$('global-search-count'),root=$('global-search-results');
  root.replaceChildren();count.textContent='正在搜尋地名…';
  try{
    const endpoint=new URL('https://photon.komoot.io/api/');
    const {lat,lng}=map.getCenter();
    const normalized=query.normalize('NFKC').trim();
    const prefix=/^(?:中國大陸|中国大陆|大陸|大陆)[\s、，,:：-]*/u;
    const mainland=prefix.test(normalized);
    const place=normalized.replace(prefix,'').trim();
    if(!place){count.textContent='請在地區名稱後輸入要找的地名';return;}
    const simplified=simplifyPlaceName(place);
    const xiagong=/^下宫(?:镇|乡)?$/u.test(simplified);
    const searchTerms=xiagong?['下宫镇',simplified]:mainland?[simplified,place]:[place,simplified];
    let features=[];
    for(const term of new Set(searchTerms)){
      endpoint.search=new URLSearchParams({q:term,limit:'10',lat:String(lat),lon:String(lng)});
      if(mainland)endpoint.searchParams.set('countrycode','CN');
      const response=await fetch(endpoint,{signal:controller.signal});
      if(!response.ok)throw Error();
      const data=await response.json();
      features=Array.isArray(data.features)?data.features:[];
      if(mainland)features=features.filter(feature=>feature.properties?.countrycode?.toUpperCase()==='CN');
      if(features.some(feature=>feature.geometry?.type==='Point'&&feature.properties?.name))break;
    }
    if(controller.signal.aborted||!searchDialog.open)return;
    for(const feature of features){
      const [lon,lat]=feature.geometry?.coordinates||[];
      const p=feature.properties||{};
      if(feature.geometry?.type!=='Point'||!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180||!p.name)continue;
      const row=document.createElement('button');
      row.className='ux-result';
      const label=document.createElement('b'),detail=document.createElement('small');
      label.textContent=xiagong&&p.name==='下宫镇'?'下宮鎮':p.name;
      detail.textContent=[...new Set([p.city,p.state,p.country].filter(Boolean))].join(' · ');
      row.append(label,detail);
      row.onclick=()=>locateSearchResult({kind:'地名',name:label.textContent,points:[[lat,lon]]});
      root.append(row);
    }
    count.textContent=root.childElementCount?'找到 '+root.childElementCount+' 個地名，點選可在地圖上標示':'圖資未找到符合的地名。可加上縣市、改用舊名，或關閉地名模式後貼上經緯度定位。';
    if(query.normalize('NFKC')==='小祚'){
      const suggestion=document.createElement('button');
      suggestion.type='button';
      suggestion.className='ux-result';
      suggestion.textContent='可能想找：小岞鎮（福建泉州惠安）';
      suggestion.onclick=()=>{
        $('global-search-input').value='小岞镇';
        requestPlaceSuggestions();
      };
      root.prepend(suggestion);
    }
  }catch{
    if(!controller.signal.aborted||controller.signal.reason==='timeout')count.textContent='地名服務暫時無法使用，請稍後重試';
  }finally{clearTimeout(timeout);if(placeRequest===controller)placeRequest=null;}
};

